"""Independent Akiyama public factory facts with conservative manual native subsets."""
from curated import add, profile

AKIYAMA_REMAINING_REFERENCES={'Akiyama Pulsar': {'url': 'https://dmsdown.com/descargas/DMS_DJPROMIXER/DJProMixer_3.0_Setup.exe', 'sha256': '0557173bb5cb8bce866bbd439bd10140d8c281fd550486541dc4ddfff46edbec', 'members': [{'path': 'Devices/AKIYAMA PULSAR.xml', 'sha256': '88965a83c862f1f555ec0d2cf61d8c36fe793b9ec013754702afefc0334c5ac6'}], 'review': 'Independent visible public factory XML qualifies only a manual A/B normal-layer subset on wire channels0/1 and centre controls on0. Each model file was checked separately. No sibling controls or factory release/action code is copied. Shift45 appears in the factory unused-control declarations on both side channels. Native uses Hold mode, composes the two held inputs and retires source-owned holds. Normal buttons, four Hot Cues, five strip controls and three global controls are retained. C/D, configurable channels/modes, alternate commands, calibration, feedback/lifecycle/audio and physical/iPad/A10X acceptance remain open.'}, 'Akiyama Tempus': {'url': 'https://dmsdown.com/descargas/DMS_DJPROMIXER/DJProMixer_3.0_Setup.exe', 'sha256': '0557173bb5cb8bce866bbd439bd10140d8c281fd550486541dc4ddfff46edbec', 'members': [{'path': 'Devices/AKIYAMA TEMPUS.xml', 'sha256': '8dd48dd36698d64ed452f7bcb7ab4dccc949404fdc090707a0831218f723d274'}], 'review': 'Independent visible public factory XML qualifies only a manual A/B normal-layer subset on wire channels0/1 and centre controls on0. Each model file was checked separately. No sibling controls or factory release/action code is copied. Shift45 appears in the factory unused-control declarations on both side channels. Native uses Hold mode, composes the two held inputs and retires source-owned holds. Normal buttons, four Hot Cues, five strip controls and three global controls are retained. C/D, configurable channels/modes, alternate commands, calibration, feedback/lifecycle/audio and physical/iPad/A10X acceptance remain open.'}, 'Akiyama Syncron': {'url': 'https://dmsdown.com/descargas/DMS_DJPROMIXER/DJProMixer_3.0_Setup.exe', 'sha256': '0557173bb5cb8bce866bbd439bd10140d8c281fd550486541dc4ddfff46edbec', 'members': [{'path': 'Devices/AKIYAMA SYNCRON.xml', 'sha256': '52d924e47918e87247a450e95d9b920ee541d535ebc9dc044a544f59e6fb28cc'}], 'review': 'Separate public ProMixer XML and DEX Syncron script agree on eleven absolute mixer wires: five per deck on explicit channels0/1, and crossfader48 on centre channel4. Native retains only those shared facts. ProMixer Sync96 differs from DEX33. ProMixer loop In/Out0 conflicts with DEX2/3. ProMixer headphone51 overlaps the DEX multi-byte jog interpretation. Those disputed controls, all transport/Shift/pads/jog/tempo, feedback/lifecycle/audio and physical/iPad/A10X acceptance remain inactive/open. No source executable or downloaded mapping action is bundled or executed.', 'secondaryURL': 'https://pcdj.com/downloads/dex4/setup_dex4.0_mac.pkg', 'secondarySHA256': '55aaca2c33e7f1b84b420ab20f2c261f1c98ee73b62b3c012e25616f39070030', 'secondaryMember': 'controllers/Akiyama__Syncron.js', 'secondaryMemberSHA256': '8aeda2fa4517b8423c15849c2f31a2047fe5cba8d7f50d5c1ce0c5c2dc659685', 'disputedInputs': ['Sync96 versus33', 'Loop In/Out0 versus2/3', 'Headphone51 versus multi-byte jog interpretation']}}


def akiyama_remaining_profiles():
    results=[]
    for name,ref in AKIYAMA_REMAINING_REFERENCES.items():
        syncron=name.endswith('Syncron')
        result=profile(name,ref['url'])
        result.update(autoSelect=False,definition='reviewed:'+name.lower().replace(' ','-')+'-public-subset',
                      aliases=[name,name.split(' ',1)[1]],excludedAliases=[name+' clone'],
                      hardwareMode='Manual A/B normal-mode subset. Set deck MIDI channels1/2 and centre channel1, Shift to Hold, and mixer strips to MIDI. Do not use C/D or alternate modes. Configure audio separately.' if not syncron else 'Manual mixer-only subset. Select MIDI A and MIDI B, enable MIDI mixer control and use deck channels1/2 with centre channel5. Use app transport/jogs and configure audio separately.',
                      scope='Manual normal-layer transport, four Hot Cues, loops, mixer and held-Shift cleanup. No calibration, source mapping action or hardware write.' if not syncron else 'Manual eleven-control mixer subset shared by two independent public factory mappings. No disputed transport, headphone, jog or tempo input is enabled.',
                      gaps=['C/D and configurable channels/modes, full Shift/FX/pad controls, jog/tempo calibration, feedback/state/lifecycle/audio and physical/iPad/A10X acceptance remain open. Source scripts and installers are not executed or bundled. Factory software sensitivity values are not physical calibration.'] if not syncron else ['Sync, loop and headphone rows disagree across the two sources. All transport/Shift/pad/jog/tempo, complete feedback/state/lifecycle/audio and physical/iPad/A10X acceptance remain open. No DEX or ProMixer action, hardware reset, preset or audio route is executed.'])
        if not syncron:
            for channel in [0,1]:
                add(result,'shift',channel,45);result['inputs'][-1]['shiftInput']=channel
            result['bankChanges']=[{'channel':channel,'number':45,'onValue':127,'decks':['a','b']} for channel in [0,1]]
        for channel,deck in enumerate('ab'):
            if not syncron:
                for action,number in [('play',24),('cuePreview',23),('sync',18),('load',34+channel),('keylock',16),('cue',28),('loopIn',4),('loopOut',5),('loop',6),('pitchBendDown',19),('pitchBendUp',20)]+[(f'hotcue{slot+1}',8+slot) for slot in range(4)]:
                    add(result,action,channel,number,deck=deck);result['inputs'][-1]['shifted']=False
            controls=[('level',16+16*channel),('gain',17+16*channel),('high',18+16*channel),('mid',19+16*channel),('low',20+16*channel)] if syncron else [('gain',3),('high',4),('mid',5),('low',6),('level',7)]
            for action,number in controls:add(result,action,channel,number,'control',deck=deck)
        if syncron:add(result,'crossfader',4,48,'control')
        else:
            for action,number in [('crossfader',16),('cueMix',19),('monitor',20)]:add(result,action,0,number,'control')
        results.append(result)
    return results
